function evidence = f90_xrobo10_extract_reference_evidence(modelPath,outDir)
%f90_xrobo10_extract_reference_evidence Exact-reference replay bridge.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end
scriptRoot = fileparts(mfilename("fullpath"));
sourceRoot = fileparts(modelPath);
scenarioPath = string(getenv("SIMUVERITY_OFFICIAL_SCENARIOS"));
assert(isfile(scenarioPath),"SimuVerity:F90:XROBO10:ScenarioContract", ...
    "The evaluator-owned official scenario contract is missing.");
contract = jsondecode(fileread(scenarioPath));
assert(string(contract.task_id) == "F90-XROBO-10", ...
    "SimuVerity:F90:XROBO10:ScenarioContract", ...
    "The official scenario contract belongs to another task.");
official = struct( ...
    "reference",struct("model_file_presence", ...
        "present"), ...
    "simulation",contract.simulation, ...
    "scenarios",contract.scenarios);
modelFile = modelPath;
localVerifyAssets(sourceRoot,official);

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
if strlength(generationRunId) == 0, generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID")); end
if strlength(generationRunId) == 0, generationRunId = "reference_replay"; end
assert(~isfolder(outDir),"SimuVerity:F90:XROBO10:OutputReuse", ...
    "Evidence output already exists for GenerationRunId %s.",generationRunId);
mkdir(outDir);
workspace = string(tempname);
mkdir(workspace);
workspaceCleanup = onCleanup(@() localRemoveTree(workspace)); %#ok<NASGU>

cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:F90:XROBO10:Isolation", ...
    "Isolated cache and codegen folders are required.");
Simulink.fileGenControl("set","CacheFolder",cacheDir, ...
    "CodeGenFolder",codegenDir,"createDir",true);
set(groot,"defaultFigureVisible","off");
addpath(sourceRoot,"-begin");
addpath(scriptRoot,"-begin");
assert(startsWith(string(which("attachBall")),string(scriptRoot)), ...
    "SimuVerity:F90:XROBO10:EventTapPrecedence", ...
    "The non-invasive event tap helper is not first on path.");

originalDirectory = pwd;
directoryCleanup = onCleanup(@() cd(originalDirectory)); %#ok<NASGU>
cd(workspace);
copyfile(fullfile(sourceRoot,"*"),workspace);
eventHelpers = [ ...
    "attachBall.m","attachCup.m","destroyCupPhys1.m", ...
    "destroyCupPhys2.m","detachBallPhys1.m","detachBallPhys2.m", ...
    "detachCupPhys1.m","detachCupPhys2.m"];
for helper = eventHelpers
    copyfile(fullfile(scriptRoot,helper),fullfile(workspace,helper));
end
runtimeModelFile = fullfile(workspace,"smart4iRobotDynamics.slx");
assert(isfile(runtimeModelFile),"SimuVerity:F90:XROBO10:RuntimeCopy", ...
    "The isolated runtime model copy is missing.");
assert(contains(fileread(which("attachBall")), ...
    "f90_xrobo10_log_event"),"SimuVerity:F90:XROBO10:EventTapPrecedence", ...
    "The isolated runtime helper does not contain the event tap.");
model = "smart4iRobotDynamics";
evidence = struct( ...
    "schema","simuverity.f90-xrobo10-evidence.v1", ...
    "task_id","F90-XROBO-10", ...
    "reference_substantive_modifications",0, ...
    "extraction_only",true, ...
    "contains_score_decisions",false, ...
    "load_pass",false, ...
    "update_pass",false, ...
    "compile_pass",false, ...
    "nominal_smoke_pass",false, ...
    "static_audit",struct, ...
    "scenarios",struct([]), ...
    "errors",struct, ...
    "started_at",localNow, ...
    "runtime",struct( ...
        "generation_run_id",generationRunId, ...
        "matlab_release",string(version("-release")), ...
        "mcp_port",string(getenv("SIMUVERITY_MCP_PORT")), ...
        "matlab_prefdir",string(getenv("MATLAB_PREFDIR")), ...
        "cache",cacheDir, ...
        "codegen",codegenDir));

try
    fprintf("F90_XROBO10_STAGE load_begin\n");
    load_system(runtimeModelFile);
    cleanup = onCleanup(@() localCloseModel(model)); %#ok<NASGU>
    evidence.load_pass = true;
    paths = localModelPaths(model);
    localInstallHarness(model,paths);
    set_param(model, ...
        "ReturnWorkspaceOutputs","on", ...
        "SignalLogging","on", ...
        "StopTime",localNumber(official.simulation.stop_s));
    localApplyScenario(model,paths,official.scenarios(1));
    fprintf("F90_XROBO10_STAGE update_begin\n");
    set_param(model,"SimulationCommand","update");
    evidence.update_pass = true;
    fprintf("F90_XROBO10_STAGE compile_begin\n");
    feval(model,[],[],[],"compile");
    feval(model,[],[],[],"term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(paths);

    fprintf("F90_XROBO10_STAGE smoke_begin\n");
    set_param(model,"StopTime","2");
    localResetEventLog;
    smoke = sim(model,"ReturnWorkspaceOutputs","on");
    localValidateSmoke(smoke);
    evidence.nominal_smoke_pass = true;
    clear smoke
    set_param(model,"StopTime",localNumber(official.simulation.stop_s));

    rows = repmat(localEmptyScenario,numel(official.scenarios),1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).requested_inputs = scenario;
        try
            fprintf("F90_XROBO10_STAGE scenario_begin id=%s\n",scenario.id);
            localApplyScenario(model,paths,scenario);
            localResetEventLog;
            started = tic;
            simOut = sim(model,"ReturnWorkspaceOutputs","on");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut, ...
                double(official.simulation.evidence_resample_s));
            rows(k) = localFinalizeScenario(rows(k),outputs);
            fprintf("F90_XROBO10_STAGE scenario_end id=%s valid=%d wall=%.3f\n", ...
                scenario.id,rows(k).valid,rows(k).simulation_wall_clock_s);
            clear simOut
        catch ME
            rows(k).error = localError(ME);
            fprintf("F90_XROBO10_SCENARIO_ERROR id=%s identifier=%s message=%s\n", ...
                scenario.id,ME.identifier,ME.message);
        end
    end
    evidence.scenarios = rows;
catch ME
    evidence.errors.session = localError(ME);
    fprintf("F90_XROBO10_SESSION_ERROR identifier=%s message=%s\n", ...
        ME.identifier,ME.message);
end

localCloseModel(model);
evidence.model_closed_without_save = ~bdIsLoaded(model);
evidence.finished_at = localNow;
evidencePath = fullfile(outDir,"evidence.json");
localWriteJson(evidencePath,evidence);
validCount = 0;
if ~isempty(evidence.scenarios)
    validCount = sum([evidence.scenarios.valid]);
end
fprintf("F90_XROBO10_EVIDENCE load=%d update=%d compile=%d smoke=%d valid=%d/%d path=%s\n", ...
    evidence.load_pass,evidence.update_pass,evidence.compile_pass, ...
    evidence.nominal_smoke_pass,validCount,numel(evidence.scenarios), ...
    evidencePath);
end

function paths = localModelPaths(model)
paths = struct( ...
    "chart",model + "/Chart", ...
    "ball",model + "/Ball Instance", ...
    "robot1_motion",model + "/Robot1 Motion Control", ...
    "robot2_motion",model + "/Robot2 Motion Control", ...
    "robot1_dynamics",model + ...
        "/Robot1 Motion Control/Robot1 Dynamics & Control", ...
    "robot2_dynamics",model + ...
        "/Robot2 Motion Control/Robot2 Dynamics & Control");
paths.robot1_trajectory = localFindOne(paths.robot1_dynamics, ...
    "Trapezoidal Velocity.*Trajectory");
paths.robot2_trajectory = localFindOne(paths.robot2_dynamics, ...
    "Trapezoidal Velocity.*Trajectory");
paths.robot1_manipulator = paths.robot1_dynamics + ...
    "/Manipulator Dynamics";
paths.robot2_manipulator = paths.robot2_dynamics + ...
    "/Manipulator Dynamics";
paths.robot1_torque = paths.robot1_dynamics + "/Torque Controller";
paths.robot2_torque = paths.robot2_dynamics + "/Torque Controller";
names = fieldnames(paths);
for k = 1:numel(names)
    assert(getSimulinkBlockHandle(paths.(names{k})) > 0, ...
        "SimuVerity:F90:XROBO10:BlockLookup", ...
        "Required block is missing: %s",paths.(names{k}));
end
end

function block = localFindOne(parent,pattern)
matches = find_system(parent,"SearchDepth",1,"RegExp","on", ...
    "Name",pattern);
matches = string(matches);
matches(matches == parent) = [];
assert(numel(matches) == 1,"SimuVerity:F90:XROBO10:BlockLookup", ...
    "Expected one block matching %s below %s; found %d.", ...
    pattern,parent,numel(matches));
block = matches(1);
end

function localInstallHarness(model,paths)
for display = ["Display","Display1"]
    block = model + "/" + display;
    if getSimulinkBlockHandle(block) > 0
        set_param(block,"Commented","on");
    end
end
localTap(model,paths.chart,1,"f90_shuttle1");
localTap(model,paths.chart,2,"f90_shuttle2");
localTap(model,paths.chart,3,"f90_shuttle3");
localTap(model,paths.chart,4,"f90_shuttle4");
localTap(model,paths.chart,5,"f90_robot1_go");
localTap(model,paths.chart,6,"f90_robot1_shuttle");
localTap(model,paths.chart,7,"f90_robot2_go");
localTap(model,paths.chart,8,"f90_robot2_shuttle");
localTap(model,paths.chart,9,"f90_ball_instance");
localTap(model,paths.chart,10,"f90_unload_instance");
localTap(model,paths.chart,11,"f90_destroy_stage1");
localTap(model,paths.chart,12,"f90_destroy_stage2");
localTap(model,paths.robot1_motion,2,"f90_robot1_task");
localTap(model,paths.robot2_motion,2,"f90_robot2_task");

localTap(paths.robot1_dynamics,paths.robot1_trajectory,1, ...
    "f90_robot1_q_ref");
localTap(paths.robot1_dynamics,paths.robot1_trajectory,2, ...
    "f90_robot1_qd_ref");
localTap(paths.robot1_dynamics,paths.robot1_trajectory,3, ...
    "f90_robot1_qdd_ref");
localTap(paths.robot1_dynamics,paths.robot1_manipulator,1, ...
    "f90_robot1_q");
localTap(paths.robot1_dynamics,paths.robot1_manipulator,2, ...
    "f90_robot1_qd");
localTap(paths.robot1_dynamics,paths.robot1_manipulator,3, ...
    "f90_robot1_qdd");
localTap(paths.robot1_dynamics,paths.robot1_torque,1, ...
    "f90_robot1_tau");

localTap(paths.robot2_dynamics,paths.robot2_trajectory,1, ...
    "f90_robot2_q_ref");
localTap(paths.robot2_dynamics,paths.robot2_trajectory,2, ...
    "f90_robot2_qd_ref");
localTap(paths.robot2_dynamics,paths.robot2_trajectory,3, ...
    "f90_robot2_qdd_ref");
localTap(paths.robot2_dynamics,paths.robot2_manipulator,1, ...
    "f90_robot2_q");
localTap(paths.robot2_dynamics,paths.robot2_manipulator,2, ...
    "f90_robot2_qd");
localTap(paths.robot2_dynamics,paths.robot2_manipulator,3, ...
    "f90_robot2_qdd");
localTap(paths.robot2_dynamics,paths.robot2_torque,1, ...
    "f90_robot2_tau");
end

function localTap(parent,source,port,variable)
tap = parent + "/F90 " + variable + " Tap";
add_block("simulink/Sinks/To Workspace",tap, ...
    "VariableName",variable,"SaveFormat","Timeseries", ...
    "MaxDataPoints","inf");
sourcePorts = get_param(source,"PortHandles");
tapPorts = get_param(tap,"PortHandles");
assert(numel(sourcePorts.Outport) >= port && ...
    sourcePorts.Outport(port) > 0 && tapPorts.Inport(1) > 0, ...
    "SimuVerity:F90:XROBO10:TapPort", ...
    "A required real source port is missing: %s port %d.", ...
    source,port);
add_line(parent,sourcePorts.Outport(port),tapPorts.Inport(1), ...
    "autorouting","on");
end

function localApplyScenario(model,paths,scenario)
offset = reshape(double(scenario.BallOffsetXY),1,2);
assert(all(isfinite(offset)) && all(abs(offset) <= 0.0300001), ...
    "SimuVerity:F90:XROBO10:BallOffset", ...
    "BallOffsetXY must remain within the supported range.");
assignin("base","BallOffsetXY",offset);
translation = [-0.25 + offset(1),-0.25 + offset(2),0.035];
ballScript = sprintf( ...
    "Actor.createShape('sphere', [0.07 0.07 0.07]);\n" + ...
    "Actor.Color=[1 0 0];\n" + ...
    "Actor.Translation=[%.17g %.17g %.17g];\n" + ...
    "Actor.Mobility=sim3d.utils.MobilityTypes.Movable;\n" + ...
    "Actor.ConstantAttributes=false;",translation);
set_param(paths.ball, ...
    "InitScriptText",ballScript, ...
    "Translation",mat2str(translation,17));
set_param(model,"SimulationCommand","update");
end

function localValidateSmoke(simOut)
names = ["f90_robot1_q_ref","f90_robot1_q", ...
    "f90_robot1_tau","f90_robot2_q_ref","f90_robot2_q", ...
    "f90_robot2_tau","f90_shuttle1","f90_robot1_task", ...
    "f90_robot2_task"];
for name = names
    value = localGetOutput(simOut,name);
    assert(isa(value,"timeseries") && numel(value.Time) >= 1, ...
        "SimuVerity:F90:XROBO10:SmokeTap", ...
        "Smoke run did not produce %s.",name);
end
end

function outputs = localExtractOutputs(simOut,resampleStep)
seriesNames = [ ...
    "f90_robot1_q_ref","f90_robot1_qd_ref","f90_robot1_qdd_ref", ...
    "f90_robot1_q","f90_robot1_qd","f90_robot1_qdd", ...
    "f90_robot1_tau","f90_robot2_q_ref","f90_robot2_qd_ref", ...
    "f90_robot2_qdd_ref","f90_robot2_q","f90_robot2_qd", ...
    "f90_robot2_qdd","f90_robot2_tau","f90_shuttle1", ...
    "f90_shuttle2","f90_shuttle3","f90_shuttle4", ...
    "f90_robot1_go","f90_robot1_shuttle","f90_robot2_go", ...
    "f90_robot2_shuttle","f90_ball_instance", ...
    "f90_destroy_stage1","f90_destroy_stage2", ...
    "f90_robot1_task","f90_robot2_task"];
series = struct;
endTime = Inf;
for name = seriesNames
    field = extractAfter(name,"f90_");
    series.(field) = localWorkspaceSeries(simOut,name);
    endTime = min(endTime,max(series.(field).time));
end
assert(isfinite(endTime) && endTime >= 1, ...
    "SimuVerity:F90:XROBO10:SimulationTime", ...
    "Simulation did not advance far enough for evidence.");
time = (0:resampleStep:endTime)';
if time(end) < endTime - 1e-9
    time(end + 1,1) = endTime;
end
at = @(name) localInterpMatrix(series.(name),time,"previous");
robot1Reference = [at("robot1_q_ref"),at("robot1_qd_ref"), ...
    at("robot1_qdd_ref")];
robot1State = [at("robot1_q"),at("robot1_qd"),at("robot1_qdd")];
robot2Reference = [at("robot2_q_ref"),at("robot2_qd_ref"), ...
    at("robot2_qdd_ref")];
robot2State = [at("robot2_q"),at("robot2_qd"),at("robot2_qdd")];
lineSupervisor = [at("shuttle1"),at("shuttle2"),at("shuttle3"), ...
    at("shuttle4"),at("robot1_go"),at("robot1_shuttle"), ...
    at("robot2_go"),at("robot2_shuttle"),at("ball_instance"), ...
    at("destroy_stage1"),at("destroy_stage2")];
taskState = [at("robot1_task"),at("robot2_task")];
eventLog = localEventLog;
actorState = localActorState(time,eventLog);
outputs = struct( ...
    "time_s",time, ...
    "robot1_joint_reference",robot1Reference, ...
    "robot1_joint_state",robot1State, ...
    "robot1_joint_torque",at("robot1_tau"), ...
    "robot2_joint_reference",robot2Reference, ...
    "robot2_joint_state",robot2State, ...
    "robot2_joint_torque",at("robot2_tau"), ...
    "line_supervisor",lineSupervisor, ...
    "task_state",taskState, ...
    "actor_transfer_state",actorState, ...
    "actor_event_log",eventLog);
end

function log = localEventLog
try
    log = double(evalin("base","F90_XROBO10_EventLog"));
catch
    log = zeros(0,3);
end
if isempty(log), log = zeros(0,3); end
assert(size(log,2) == 3,"SimuVerity:F90:XROBO10:EventLog", ...
    "The actor event log has an invalid width.");
end

function state = localActorState(time,eventLog)
state = zeros(numel(time),5);
current = zeros(1,5);
eventIndex = 1;
for k = 1:numel(time)
    while eventIndex <= size(eventLog,1) && ...
            eventLog(eventIndex,1) <= time(k) + 1e-9
        code = round(eventLog(eventIndex,2));
        switch code
            case 1
                current(1) = 1;
            case 2
                current(1) = 0;
            case 3
                current(2) = 1;
            case 4
                current(3) = 1;
            case 5
                current(3) = 0;
            case 6
                current(4) = 1;
            case 7
                current(2) = 0;
            case 8
                current(5) = current(5) + 1;
                current(4) = 0;
        end
        eventIndex = eventIndex + 1;
    end
    state(k,:) = current;
end
end

function row = localFinalizeScenario(row,outputs)
required = { ...
    outputs.time_s,outputs.robot1_joint_reference, ...
    outputs.robot1_joint_state,outputs.robot1_joint_torque, ...
    outputs.robot2_joint_reference,outputs.robot2_joint_state, ...
    outputs.robot2_joint_torque,outputs.line_supervisor, ...
    outputs.task_state,outputs.actor_transfer_state};
count = numel(outputs.time_s);
validShape = size(outputs.robot1_joint_reference,2) == 18 && ...
    size(outputs.robot1_joint_state,2) == 18 && ...
    size(outputs.robot1_joint_torque,2) == 6 && ...
    size(outputs.robot2_joint_reference,2) == 18 && ...
    size(outputs.robot2_joint_state,2) == 18 && ...
    size(outputs.robot2_joint_torque,2) == 6 && ...
    size(outputs.line_supervisor,2) == 19 && ...
    size(outputs.task_state,2) == 2 && ...
    size(outputs.actor_transfer_state,2) == 5;
finite = true;
sameRows = true;
for k = 1:numel(required)
    finite = finite && all(isfinite(required{k}),"all");
    sameRows = sameRows && size(required{k},1) == count;
end
row.simulation_pass = true;
row.required_evidence_pass = finite && sameRows && validShape && ...
    count >= 21 && abs(outputs.time_s(1)) < 1e-12;
row.valid = row.required_evidence_pass;
row.sample_count = count;
row.start_time_s = outputs.time_s(1);
row.end_time_s = outputs.time_s(end);
row.actor_event_count = size(outputs.actor_event_log,1);
eventCodes = unique(round(outputs.actor_event_log(:,2)));
row.required_actor_events_pass = all(ismember([1 3 4 6 8], ...
    eventCodes'));
row.valid = row.valid && row.required_actor_events_pass;
row.outputs = outputs;
row.error = struct;
end

function audit = localStaticAudit(paths)
audit = struct( ...
    "two_robot_workcells", ...
        getSimulinkBlockHandle(paths.robot1_motion) > 0 && ...
        getSimulinkBlockHandle(paths.robot2_motion) > 0, ...
    "robot1_reference_to_torque", ...
        localPortConnects(paths.robot1_trajectory,1,paths.robot1_torque,1) && ...
        localPortConnects(paths.robot1_trajectory,2,paths.robot1_torque,2) && ...
        localPortConnects(paths.robot1_trajectory,3,paths.robot1_torque,3), ...
    "robot1_torque_to_dynamics", ...
        localPortConnects(paths.robot1_torque,1, ...
        paths.robot1_manipulator,1), ...
    "robot1_position_velocity_feedback", ...
        localPortConnects(paths.robot1_manipulator,1, ...
        paths.robot1_torque,4) && ...
        localPortConnects(paths.robot1_manipulator,2, ...
        paths.robot1_torque,5), ...
    "robot2_reference_to_torque", ...
        localPortConnects(paths.robot2_trajectory,1,paths.robot2_torque,1) && ...
        localPortConnects(paths.robot2_trajectory,2,paths.robot2_torque,2) && ...
        localPortConnects(paths.robot2_trajectory,3,paths.robot2_torque,3), ...
    "robot2_torque_to_dynamics", ...
        localPortConnects(paths.robot2_torque,1, ...
        paths.robot2_manipulator,1), ...
    "robot2_position_velocity_feedback", ...
        localPortConnects(paths.robot2_manipulator,1, ...
        paths.robot2_torque,4) && ...
        localPortConnects(paths.robot2_manipulator,2, ...
        paths.robot2_torque,5), ...
    "supervisor_drives_four_shuttles", ...
        all(arrayfun(@(index) localOutputConnected(paths.chart,index),1:4)), ...
    "supervisor_drives_both_robots", ...
        all(arrayfun(@(index) localOutputConnected(paths.chart,index),5:8)), ...
    "actor_event_helpers_active", ...
        contains(fileread(which("attachBall")), ...
        "f90_xrobo10_log_event"));
fields = fieldnames(audit);
audit.core_path_qualified = all(cellfun( ...
    @(name) logical(audit.(name)),fields));
end

function pass = localPortConnects(source,outIndex,destination,inIndex)
pass = false;
try
    sourcePorts = get_param(source,"PortHandles");
    destinationPorts = get_param(destination,"PortHandles");
    line = get_param(sourcePorts.Outport(outIndex),"Line");
    destinations = get_param(line,"DstPortHandle");
    pass = any(destinations == destinationPorts.Inport(inIndex));
catch
end
end

function pass = localOutputConnected(source,outIndex)
pass = false;
try
    ports = get_param(source,"PortHandles");
    line = get_param(ports.Outport(outIndex),"Line");
    pass = line > 0 && ~isempty(get_param(line,"DstPortHandle"));
catch
end
end

function series = localWorkspaceSeries(simOut,name)
value = localGetOutput(simOut,name);
assert(isa(value,"timeseries"),"SimuVerity:F90:XROBO10:WorkspaceTap", ...
    "Required measurement tap %s is missing.",name);
raw = double(value.Data);
sampleCount = numel(value.Time);
dimensions = size(raw);
if sampleCount == 1
    data = reshape(raw,1,[]);
else
    timeDimension = [];
    if dimensions(1) == sampleCount
        timeDimension = 1;
    elseif dimensions(end) == sampleCount
        timeDimension = numel(dimensions);
    else
        matches = find(dimensions == sampleCount,1,"first");
        if ~isempty(matches), timeDimension = matches; end
    end
    assert(~isempty(timeDimension),"SimuVerity:F90:XROBO10:WorkspaceShape", ...
        "Tap %s has no dimension matching its %d timestamps.", ...
        name,sampleCount);
    order = [timeDimension,setdiff(1:numel(dimensions), ...
        timeDimension,"stable")];
    data = reshape(permute(raw,order),sampleCount,[]);
end
assert(size(data,1) == sampleCount && ~isempty(data), ...
    "SimuVerity:F90:XROBO10:WorkspaceShape", ...
    "Tap %s has unexpected dimensions.",name);
series = struct("time",double(value.Time(:)),"values",data);
end

function values = localInterpMatrix(series,time,method)
sourceTime = double(series.time(:));
sourceValues = double(series.values);
if isvector(sourceValues), sourceValues = sourceValues(:); end
[sourceTime,uniqueIndex] = unique(sourceTime,"stable");
sourceValues = sourceValues(uniqueIndex,:);
if numel(sourceTime) == 1
    values = repmat(sourceValues(1,:),numel(time),1);
else
    values = interp1(sourceTime,sourceValues,time,method,"extrap");
end
values = double(values);
end

function output = localGetOutput(simOut,name)
output = [];
try, output = simOut.get(name); catch, end
if isempty(output)
    try, output = evalin("base",name); catch, end
end
end

function localResetEventLog
assignin("base","F90_XROBO10_EventLog",zeros(0,3));
end

function row = localEmptyScenario
row = struct( ...
    "id","", ...
    "requested_inputs",struct, ...
    "simulation_pass",false, ...
    "required_evidence_pass",false, ...
    "valid",false, ...
    "simulation_wall_clock_s",0, ...
    "sample_count",0, ...
    "start_time_s",0, ...
    "end_time_s",0, ...
    "actor_event_count",0, ...
    "required_actor_events_pass",false, ...
    "outputs",struct, ...
    "error",struct);
end

function localVerifyAssets(sourceRoot,official)
expected = { ...
    "smart4iRobotDynamics.slx",official.reference.model_file_presence; ...
    "smart4i_robotRBT.mat", ...
        "present"; ...
    "smart4i_scene.mat", ...
        "present"; ...
    "smart4i_coords.mat", ...
        "present"};
for k = 1:size(expected,1)
    path = fullfile(sourceRoot,expected{k,1});
    assert(isfile(path),"SimuVerity:F90:XROBO10:AssetMissing", ...
        "Pinned runtime asset is missing: %s",expected{k,1});
    actual = localFilePresence(path);
    assert(strcmpi(actual,expected{k,2}), ...
        "SimuVerity:F90:XROBO10:AssetBinding", ...
        "Pinned runtime asset binding mismatch: %s",expected{k,1});
end
end

function binding = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
binding = "present";
end

function localWriteJson(path,value)
fid = fopen(path,"w");
assert(fid > 0,"SimuVerity:F90:XROBO10:JsonWrite", ...
    "Could not open JSON output: %s",path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
bytes = unicode2native(jsonencode(value,PrettyPrint=true),"UTF-8");
fwrite(fid,bytes,"uint8");
end

function info = localError(ME)
info = struct("identifier",string(ME.identifier), ...
    "message",string(ME.message), ...
    "stack",arrayfun(@(frame) struct( ...
        "file",string(frame.file), ...
        "name",string(frame.name), ...
        "line",double(frame.line)),ME.stack));
end

function value = localNumber(value)
value = sprintf("%.17g",double(value));
end

function localCloseModel(model)
try
    if bdIsLoaded(model), close_system(model,0); end
catch
end
end

function localRemoveTree(root)
try
    if isfolder(root), rmdir(root,"s"); end
catch
end
end

function value = localNow
value = string(datetime("now","TimeZone","local", ...
    "Format","yyyy-MM-dd'T'HH:mm:ssXXX"));
end

function root = localRepoRoot
root = fileparts(fileparts(fileparts(fileparts( ...
    fileparts(mfilename("fullpath"))))));
end
